"""Actor identity files and did:key helpers."""

from __future__ import annotations

import os
import random
import re
from datetime import UTC, datetime
from enum import StrEnum
from pathlib import Path

import base58
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey
from pydantic import BaseModel, Field

from authsome.paths import get_client_home

_ED25519_MULTICODEC_PREFIX = b"\xed\x01"
_DID_KEY_PREFIX = "did:key:z"
_HANDLE_RE = re.compile(r"^[a-z0-9][a-z0-9-]*[a-z0-9]$")

_ADJECTIVES = (
    "brisk",
    "calm",
    "clear",
    "eager",
    "fresh",
    "gentle",
    "honest",
    "kind",
    "lively",
    "quiet",
    "rapid",
    "steady",
    "swift",
    "vivid",
)
_ADVERBS = (
    "boldly",
    "brightly",
    "clearly",
    "deeply",
    "easily",
    "firmly",
    "gladly",
    "lightly",
    "quickly",
    "smoothly",
    "warmly",
    "wisely",
)


class IdentityStatus(StrEnum):
    """Progressive local lifecycle state for an identity."""

    UNREGISTERED = "unregistered"
    REGISTERED = "registered"
    CLAIMED = "claimed"


class IdentityMetadata(BaseModel):
    """Local identity metadata stored beside the caller private key."""

    handle: str
    did: str
    identity_status: IdentityStatus = IdentityStatus.UNREGISTERED
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))

    @property
    def registered(self) -> bool:
        return self.identity_status in {IdentityStatus.REGISTERED, IdentityStatus.CLAIMED}

    @property
    def claimed(self) -> bool:
        return self.identity_status == IdentityStatus.CLAIMED


def identities_dir(home: Path) -> Path:
    return get_client_home(home) / "identities"


def identity_metadata_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.json"


def identity_key_path(home: Path, handle: str) -> Path:
    return identities_dir(home) / f"{handle}.key"


def generate_handle() -> str:
    """Generate a human-readable identity handle."""
    return "-".join(
        (
            random.choice(_ADJECTIVES),
            random.choice(_ADVERBS),
            random.choice(_ADVERBS),
            f"{random.SystemRandom().randint(0, 9999):04d}",
        )
    )


def validate_handle(handle: str) -> str:
    if not _HANDLE_RE.match(handle):
        raise ValueError(f"Invalid identity handle: {handle}")
    return handle


def public_key_to_did_key(public_key: Ed25519PublicKey) -> str:
    raw = public_key.public_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PublicFormat.Raw,
    )
    return _DID_KEY_PREFIX + base58.b58encode(_ED25519_MULTICODEC_PREFIX + raw).decode("ascii")


def public_key_from_did_key(did: str) -> Ed25519PublicKey:
    if not did.startswith(_DID_KEY_PREFIX):
        raise ValueError("Only did:key Ed25519 identifiers are supported")
    try:
        decoded = base58.b58decode(did[len(_DID_KEY_PREFIX) :])
    except ValueError as exc:
        raise ValueError("Malformed did:key value") from exc
    if not decoded.startswith(_ED25519_MULTICODEC_PREFIX):
        raise ValueError("did:key does not use the Ed25519 multicodec prefix")
    raw_key = decoded[len(_ED25519_MULTICODEC_PREFIX) :]
    if len(raw_key) != 32:
        raise ValueError("Ed25519 did:key public key must be 32 bytes")
    return Ed25519PublicKey.from_public_bytes(raw_key)


def private_key_to_hex(private_key: Ed25519PrivateKey) -> str:
    raw = private_key.private_bytes(
        encoding=serialization.Encoding.Raw,
        format=serialization.PrivateFormat.Raw,
        encryption_algorithm=serialization.NoEncryption(),
    )
    return raw.hex()


def private_key_from_hex(value: str) -> Ed25519PrivateKey:
    try:
        raw = bytes.fromhex(value.strip())
    except ValueError as exc:
        raise ValueError("Malformed Ed25519 private key hex") from exc
    if len(raw) != 32:
        raise ValueError("Ed25519 private key must be 32 bytes")
    return Ed25519PrivateKey.from_private_bytes(raw)


def load_private_key(home: Path, handle: str) -> Ed25519PrivateKey:
    return private_key_from_hex(identity_key_path(home, handle).read_text(encoding="utf-8"))


def load_identity(home: Path, handle: str) -> IdentityMetadata:
    return IdentityMetadata.model_validate_json(identity_metadata_path(home, handle).read_text(encoding="utf-8"))


def identity_exists(home: Path, handle: str) -> bool:
    return identity_metadata_path(home, handle).exists() and identity_key_path(home, handle).exists()


def create_identity(home: Path, handle: str | None = None) -> IdentityMetadata:
    """Create a local identity and private key, returning existing metadata if present."""
    from authsome.cli.client_config import load_client_config, save_client_config

    resolved_handle = validate_handle(handle or _unique_handle(home))
    if identity_exists(home, resolved_handle):
        return load_identity(home, resolved_handle)

    directory = identities_dir(home)
    directory.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(directory, 0o700)
    except OSError:
        pass

    private_key = Ed25519PrivateKey.generate()
    did = public_key_to_did_key(private_key.public_key())
    now = datetime.now(UTC)
    metadata = IdentityMetadata(
        handle=resolved_handle,
        did=did,
        created_at=now,
        updated_at=now,
    )

    key_path = identity_key_path(home, resolved_handle)
    metadata_path = identity_metadata_path(home, resolved_handle)
    key_path.write_text(private_key_to_hex(private_key) + "\n", encoding="utf-8")
    try:
        os.chmod(key_path, 0o600)
    except OSError:
        pass
    metadata_path.write_text(metadata.model_dump_json(indent=2), encoding="utf-8")
    config = load_client_config(home)
    save_client_config(home, config.model_copy(update={"active_identity": metadata.handle}))
    return metadata


def remove_legacy_default_identity(home: Path) -> None:
    """Remove legacy local files for the implicit default identity."""
    for path in (identity_metadata_path(home, "default"), identity_key_path(home, "default")):
        try:
            path.unlink()
        except FileNotFoundError:
            pass


def mark_registered(home: Path, handle: str) -> IdentityMetadata:
    """Persist a registered state for a local identity after daemon registration."""
    metadata = load_identity(home, handle)
    if metadata.identity_status == IdentityStatus.CLAIMED:
        return metadata
    updated = metadata.model_copy(
        update={"identity_status": IdentityStatus.REGISTERED, "updated_at": datetime.now(UTC)}
    )
    identity_metadata_path(home, handle).write_text(updated.model_dump_json(indent=2), encoding="utf-8")
    return updated


def mark_claimed(home: Path, handle: str) -> IdentityMetadata:
    """Persist a claimed state for a local identity after ownership resolution."""
    metadata = load_identity(home, handle)
    updated = metadata.model_copy(update={"identity_status": IdentityStatus.CLAIMED, "updated_at": datetime.now(UTC)})
    identity_metadata_path(home, handle).write_text(updated.model_dump_json(indent=2), encoding="utf-8")
    return updated


def ensure_local_identity(home: Path, active_handle: str | None = None) -> IdentityMetadata:
    """Return the active local identity, creating one if none exists."""
    from authsome.cli.client_config import load_client_config

    remove_legacy_default_identity(home)
    if active_handle is None:
        active_handle = load_client_config(home).active_identity
    if active_handle:
        if not identity_exists(home, active_handle):
            raise FileNotFoundError(
                f"Configured identity '{active_handle}' not found at {identities_dir(home)}. "
                "Run 'authsome init' to create and register a new identity."
            )
        return load_identity(home, active_handle)
    return create_identity(home)


async def current_from_home(home: Path) -> IdentityMetadata:
    """Return the configured local identity, bootstrapping it if needed."""
    return ensure_local_identity(home)


def _unique_handle(home: Path) -> str:
    for _ in range(100):
        handle = generate_handle()
        if not identity_exists(home, handle):
            return handle
    raise RuntimeError("Unable to generate a unique identity handle")

"""Server-owned identity registry."""

from __future__ import annotations

import json
from datetime import UTC, datetime
from pathlib import Path

from pydantic import BaseModel, Field

from authsome.identity.local import public_key_from_did_key, validate_handle


class IdentityRegistration(BaseModel):
    """Registered identity binding stored by the daemon."""

    handle: str
    did: str
    created_at: datetime = Field(default_factory=lambda: datetime.now(UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(UTC))


class IdentityRegistrationError(ValueError):
    """Raised when an identity registration conflicts with existing registry state."""


class IdentityRegistry:
    """Filesystem-backed authoritative registry for daemon identity handles."""

    def __init__(self, path: Path) -> None:
        self._path = path

    def _load_all(self) -> list[IdentityRegistration]:
        try:
            raw = json.loads(self._path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            return []
        if not isinstance(raw, list):
            return []
        registrations: list[IdentityRegistration] = []
        for item in raw:
            try:
                registrations.append(IdentityRegistration.model_validate(item))
            except Exception:
                continue
        return registrations

    def _save_all(self, registrations: list[IdentityRegistration]) -> None:
        self._path.parent.mkdir(parents=True, exist_ok=True)
        self._path.write_text(
            json.dumps([registration.model_dump(mode="json") for registration in registrations], indent=2),
            encoding="utf-8",
        )

    async def register(self, *, handle: str, did: str) -> IdentityRegistration:
        """Register a handle/DID binding, idempotent only for the same pair."""
        handle = validate_handle(handle)
        public_key_from_did_key(did)

        registrations = self._load_all()

        existing = next((registration for registration in registrations if registration.handle == handle), None)
        if existing is not None:
            if existing.did == did:
                return existing
            raise IdentityRegistrationError(f"Identity handle '{handle}' is already registered")

        for registration in registrations:
            if registration.did == did:
                raise IdentityRegistrationError(f"DID is already registered to identity handle '{registration.handle}'")

        now = datetime.now(UTC)
        registration = IdentityRegistration(handle=handle, did=did, created_at=now, updated_at=now)
        registrations.append(registration)
        self._save_all(registrations)
        return registration

    async def resolve(self, handle: str) -> IdentityRegistration | None:
        for registration in self._load_all():
            if registration.handle == handle:
                return registration
        return None

    async def list_handles(self) -> list[str]:
        """Return all registered identity handles."""
        registrations = self._load_all()
        return sorted(registration.handle for registration in registrations)

"""Concrete local dependency wiring for the daemon server."""

from __future__ import annotations

import os
import secrets
from pathlib import Path
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:
    from authsome.auth import AuthService
    from authsome.store.interfaces import AppStore

from authsome.auth.models.config import ServerConfig
from authsome.identity import current_from_home
from authsome.identity.principal import (
    IdentityClaimRegistry,
    PrincipalRegistry,
    PrincipalVaultBindingRegistry,
    VaultRegistry,
)
from authsome.identity.registry import IdentityRegistry
from authsome.paths import get_authsome_home as _get_authsome_home
from authsome.paths import get_server_home as _get_server_home
from authsome.paths import get_server_log_path as _get_server_log_path
from authsome.server.identity_bootstrap import (
    HostedIdentityBootstrapService,
    IdentityBootstrapService,
    LocalIdentityBootstrapService,
)
from authsome.server.ownership import HostedOwnershipResolver, LocalOwnershipResolver, OwnershipResolver
from authsome.server.urls import build_server_base_url
from authsome.store.local import LocalAppStore
from authsome.vault import Vault


def get_authsome_home() -> Path:
    """Return the local Authsome home directory."""
    return _get_authsome_home()


def get_server_home(home: Path | None = None) -> Path:
    """Return the daemon-owned state directory."""
    return _get_server_home(home)


def get_server_config_path(home: Path | None = None) -> Path:
    """Return the daemon-owned config file path."""
    return get_server_home(home) / "config.json"


def get_server_log_path(home: Path | None = None) -> Path:
    """Return the daemon-owned structured log path."""
    return _get_server_log_path(home)


def get_identity_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned identity registry file path."""
    return get_server_home(home) / "identity_registry.json"


def get_principal_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned principal registry file path."""
    return get_server_home(home) / "principal_registry.json"


def get_vault_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned vault registry file path."""
    return get_server_home(home) / "vault_registry.json"


def get_identity_claim_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned identity-claim registry file path."""
    return get_server_home(home) / "identity_claim_registry.json"


def get_principal_vault_binding_registry_path(home: Path | None = None) -> Path:
    """Return the daemon-owned principal-vault binding registry file path."""
    return get_server_home(home) / "principal_vault_binding_registry.json"


def get_ui_session_secret_path(home: Path | None = None) -> Path:
    """Return the hosted UI session signing-secret path."""
    return get_server_home(home) / "ui_session_secret.key"


def get_server_base_url() -> str:
    """Return the daemon's canonical external base URL."""
    return build_server_base_url()


def get_deployment_mode() -> str:
    """Return the daemon deployment mode."""
    mode = os.environ.get("AUTHSOME_DEPLOYMENT_MODE", "local").strip().lower()
    return "hosted" if mode == "hosted" else "local"


def load_ui_session_signing_secret(home: Path | None = None) -> str:
    """Load or create the hosted UI session signing secret."""
    path = get_ui_session_secret_path(home)
    try:
        return path.read_text(encoding="utf-8").strip()
    except FileNotFoundError:
        path.parent.mkdir(parents=True, exist_ok=True)
        secret = secrets.token_hex(32)
        path.write_text(secret, encoding="utf-8")
        os.chmod(path, 0o600)
        return secret


async def get_local_ui_identity(home: Path | None = None) -> str:
    """Resolve the local active identity handle for the server-rendered UI."""
    identity = await current_from_home(home or get_authsome_home())
    return identity.handle


def load_server_config(home: Path | None = None) -> ServerConfig:
    """Load daemon-owned server config, defaulting when absent or invalid."""
    path = get_server_config_path(home)
    try:
        return ServerConfig.model_validate_json(path.read_text(encoding="utf-8"))
    except Exception:
        config = ServerConfig()
        save_server_config(config, home)
        return config


def save_server_config(config: ServerConfig, home: Path | None = None) -> None:
    """Persist daemon-owned server config."""
    path = get_server_config_path(home)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(config.model_dump_json(indent=2), encoding="utf-8")


async def create_app_store(home: Path | None = None) -> AppStore:
    """Create the daemon application store."""
    resolved_home = home or get_authsome_home()
    load_server_config(resolved_home)
    app_store = LocalAppStore(resolved_home)
    await app_store.ensure_initialized()
    return app_store


async def list_registered_identity_handles(home: Path | None = None) -> list[str]:
    """Return identity handles registered with this daemon."""
    registry = IdentityRegistry(get_identity_registry_path(home))
    return await registry.list_handles()


async def create_vault(app_store: AppStore) -> Vault:
    """Create the daemon vault from an initialized application store."""
    resolved_home = app_store.home
    config = load_server_config(resolved_home)
    return Vault(
        app_store=app_store,
        crypto_mode=config.encryption.mode,
        master_key_path=get_server_home(resolved_home) / "master.key",
    )


async def create_auth_service(
    home: Path | None = None, identity: str | None = None, vault_id: str | None = None
) -> AuthService:
    """Create an auth service scoped to an identity handle and an explicit vault_id."""
    from authsome.auth import AuthService

    if not identity:
        raise ValueError("create_auth_service requires an explicit identity handle")
    if not vault_id:
        raise ValueError("create_auth_service requires an explicit vault_id")
    store = await create_app_store(home)
    vault = await create_vault(store)
    return AuthService(vault=vault, identity=identity, vault_id=vault_id, deployment_mode=get_deployment_mode())


def create_principal_registry(home: Path | None = None) -> PrincipalRegistry:
    return PrincipalRegistry(get_principal_registry_path(home))


def create_vault_registry(home: Path | None = None) -> VaultRegistry:
    return VaultRegistry(get_vault_registry_path(home))


def create_identity_claim_registry(home: Path | None = None) -> IdentityClaimRegistry:
    return IdentityClaimRegistry(get_identity_claim_registry_path(home))


def create_principal_vault_binding_registry(home: Path | None = None) -> PrincipalVaultBindingRegistry:
    return PrincipalVaultBindingRegistry(get_principal_vault_binding_registry_path(home))


def create_ownership_resolver(home: Path | None = None) -> OwnershipResolver:
    resolved_home = home or get_authsome_home()
    principals = create_principal_registry(resolved_home)
    vaults = create_vault_registry(resolved_home)
    claims = create_identity_claim_registry(resolved_home)
    bindings = create_principal_vault_binding_registry(resolved_home)
    if get_deployment_mode() == "hosted":
        return HostedOwnershipResolver(
            principals=principals,
            vaults=vaults,
            claims=claims,
            bindings=bindings,
        )
    return LocalOwnershipResolver(
        principals=principals,
        vaults=vaults,
        bindings=bindings,
    )


def create_identity_bootstrap_service(
    identity_registry: IdentityRegistry,
    ui_sessions: Any,
    *,
    home: Path | None = None,
    server_base_url: str | None = None,
) -> IdentityBootstrapService:
    resolved_home = home or get_authsome_home()
    if get_deployment_mode() == "hosted":
        return HostedIdentityBootstrapService(
            registry=identity_registry,
            claims=create_identity_claim_registry(resolved_home),
            ui_sessions=ui_sessions,
            server_base_url=server_base_url or get_server_base_url(),
        )
    return LocalIdentityBootstrapService(registry=identity_registry)

"""Filesystem layout helpers for Authsome."""

from __future__ import annotations

import os
from pathlib import Path


def get_authsome_home(home: Path | None = None) -> Path:
    """Return the root Authsome home directory."""
    if home is not None:
        return home
    return Path(os.environ.get("AUTHSOME_HOME", str(Path.home() / ".authsome")))


def get_client_home(home: Path | None = None) -> Path:
    """Return the client-owned Authsome directory."""
    return get_authsome_home(home) / "client"


def get_server_home(home: Path | None = None) -> Path:
